package com.aitrading.journal;
import com.aitrading.ai.*;import com.aitrading.auth.UserPrincipal;import java.util.UUID;import org.springframework.stereotype.Service;
@Service public class JournalEvaluationService {private final JournalEvaluationStore store;private final AiProvider provider;public JournalEvaluationService(JournalEvaluationStore s,AiProvider p){store=s;provider=p;}public JournalEvaluationStore.Evaluation start(UserPrincipal u,UUID id,JournalEvaluationStore.Start in){var r=store.reserve(u,id,in,provider.configuration());if(!r.execute())return r.evaluation();AiJournalEvaluation out=null;AiFailure.Code fail=null;try{out=provider.evaluateJournal(r.context());}catch(AiFailure x){fail=x.code();}catch(RuntimeException x){fail=AiFailure.Code.AI_PROVIDER_UNAVAILABLE;}return store.finish(u,id,r.evaluation().requestId(),out,fail,r.reason());}}
